<div class="page-heading"><div><div class="eyebrow">ADMINISTRATION</div><h1>Manage articles</h1><p>Keep your team's answers clear and up to date. Star an article to feature it on the homepage when published.</p></div><form method="post" action="<?=e(route_url('admin'))?>"><?=csrf_field()?><input type="hidden" name="action" value="new"><button class="button primary" type="submit">New article</button></form></div>
<div class="admin-tools"><nav class="tabs" aria-label="Article status"><?php foreach(['all'=>'All','published'=>'Published','draft'=>'Drafts','trash'=>'Trash'] as $key=>$label): ?><a class="<?=$status===$key?'active':''?>" href="<?=e(route_url('admin',['status'=>$key]))?>"><?=e($label)?></a><?php endforeach; ?></nav><form method="get" class="inline-search"><input type="hidden" name="route" value="admin"><input type="hidden" name="status" value="<?=e($status)?>"><label class="sr-only" for="admin-search">Find an article</label><input id="admin-search" name="q" placeholder="Find an article…" value="<?=e($q)?>" maxlength="200"><button class="button secondary small">Find</button></form></div>
<div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Article</th><th>Status</th><th>All-time views</th><th>Last updated</th><th>Actions</th></tr></thead><tbody>
<?php foreach($results['items'] as $item): ?><tr><td><?php if($status!=='trash'): ?><a class="table-title" href="<?=e(route_url('edit',['id'=>$item['id']]))?>"><?=e($item['title'] ?: 'Untitled article')?></a><?php else: ?><strong><?=e($item['title'] ?: 'Untitled article')?></strong><?php endif; ?><small><?=e($item['category_name'] ?? 'Choose a category')?></small></td><td><span class="badge <?=$item['published_revision_id']?'published':''?>"><?=$item['trashed_at'] ? 'Trash' : ($item['published_revision_id'] ? 'Published' : 'Draft')?></span></td><td class="usage-number"><?=number_format((int)$item['view_count'])?></td><td><?=e(formatted_date($item['updated_at']))?><small><?=e($item['editor'])?></small></td><td><div class="table-actions"><?php if($status!=='trash'): ?><form method="post" action="<?=e(route_url('admin'))?>"><?=csrf_field()?><input type="hidden" name="action" value="feature"><input type="hidden" name="id" value="<?=$item['id']?>"><input type="hidden" name="version" value="<?=$item['lock_version']?>"><input type="hidden" name="featured" value="<?=$item['featured']?'0':'1'?>"><input type="hidden" name="status" value="<?=e($status)?>"><input type="hidden" name="q" value="<?=e($q)?>"><button class="link-button feature-toggle <?=$item['featured']?'is-featured':''?>" type="submit" aria-pressed="<?=$item['featured']?'true':'false'?>" aria-label="<?=e(($item['featured']?'Unfeature ':'Feature ').($item['title'] ?: 'Untitled article'))?>"><span aria-hidden="true"><?=$item['featured']?'★':'☆'?></span> <?=$item['featured']?'Featured':'Feature'?></button></form><a href="<?=e(route_url('edit',['id'=>$item['id']]))?>">Edit</a><?php endif; ?><form method="post" action="<?=e(route_url('admin'))?>" data-confirm="<?=$status==='trash' ? 'Restore this article as a draft?' : 'Move this article to Trash? Readers will no longer see it.'?>"><?=csrf_field()?><input type="hidden" name="id" value="<?=$item['id']?>"><input type="hidden" name="version" value="<?=$item['lock_version']?>"><input type="hidden" name="action" value="<?=$status==='trash'?'restore':'trash'?>"><button class="link-button <?=$status==='trash'?'':'danger-text'?>" type="submit"><?=$status==='trash'?'Restore':'Trash'?></button></form></div></td></tr><?php endforeach; ?>
<?php if(!$results['items']): ?><tr><td colspan="5" class="table-empty">No articles here yet.</td></tr><?php endif; ?></tbody></table></div>

<?php if($results['pages']>1): ?><nav class="pagination" aria-label="Admin article pages"><?php if($results['page']>1): ?><a class="button secondary" href="<?=e(route_url('admin',['status'=>$status,'q'=>$q,'page'=>$results['page']-1]))?>">← Previous</a><?php endif; ?><span>Page <?=$results['page']?> of <?=$results['pages']?></span><?php if($results['page']<$results['pages']): ?><a class="button secondary" href="<?=e(route_url('admin',['status'=>$status,'q'=>$q,'page'=>$results['page']+1]))?>">Next →</a><?php endif; ?></nav><?php endif; ?>
